<?php
declare(strict_types=1);use Joomla\CMS\Language\Text;use Joomla\CMS\Router\Route;defined('_JEXEC')or die;$s=htmlspecialchars((string)$params->get('moduleclass_sfx',''),ENT_QUOTES,'UTF-8');?>
<div class="mod-joomleague-eventranking<?php echo$s;?>"><?php if(isset($ranking['error'])):?><div class="alert alert-info mb-0"><?php echo Text::_($ranking['error']);?></div><?php elseif($ranking['definitions']===[]||$ranking['rows']===[]):?><div class="alert alert-info mb-0"><?php echo Text::_('MOD_JOOMLEAGUE_EVENTRANKING_EMPTY');?></div><?php else:?><?php if((int)$params->get('show_project_name',1)===1):?><div class="fw-bold mb-2"><?php echo htmlspecialchars((string)$ranking['project']->name,ENT_QUOTES,'UTF-8');?></div><?php endif;?><div class="list-group list-group-flush"><?php foreach($ranking['rows']as$r):$url=(string)$r->target_kind==='person'?Route::_('index.php?option=com_joomleague&view=person&person_id='.(int)$r->target_id):((string)$r->target_kind==='team'?Route::_('index.php?option=com_joomleague&view=team&team_id='.(int)$r->target_id):Route::_('index.php?option=com_joomleague&view=participant&project_id='.(int)$ranking['project']->id.'&entry_id='.(int)$r->target_id));?><a class="list-group-item list-group-item-action px-0 d-flex align-items-center gap-2" href="<?php echo$url;?>"><span class="badge text-bg-secondary rounded-pill"><?php echo(int)$r->rank;?></span><span class="flex-grow-1"><?php echo htmlspecialchars((string)$r->display_name,ENT_QUOTES,'UTF-8');?></span><strong><?php echo(int)$r->total_value;?></strong></a><?php endforeach;?></div><a class="btn btn-sm btn-outline-secondary mt-2" href="<?php echo Route::_('index.php?option=com_joomleague&view=eventranking&project_id='.(int)$ranking['project']->id.'&event_code='.rawurlencode((string)$ranking['selected_code']));?>"><?php echo Text::_('MOD_JOOMLEAGUE_EVENTRANKING_SHOW_ALL');?></a><?php endif;?></div>
